def _trim_filename(name: str, limit: int = 22) -> str:
    """Shorten long filenames to fit the card, keeping the extension visible."""
    if len(name) <= limit:
        return name
    p = Path(name)
    sfx = p.suffix
    keep = limit - len(sfx) - 1
    return p.stem[:max(keep, 4)] + "…" + sfx


